@pytest.mark.parametrize('change', ['expired', 'revision']) def test_same_current_speaker_request_rechecks_status_after_receipt_invalidated(tmp_path, change): from board.runtime.board_speaker_business import BoardSpeakerBusiness from tests.framework.test_board_business import Clock from tests.framework.test_board_speaker_business import Encoder, MODEL, quality, capture clock = Clock() service = BoardSpeakerBusiness.create(tmp_path/'public-speaker', encoder_factory=Encoder, board_boot_id='test-boot', quality=quality, expected_model_id=MODEL, anonymous_config={'enabled': True}, wall_clock=lambda: 1793400000., clock=clock, data_origin='synthetic') def say(n, text): meta, pcm = capture(n, boot='test-boot'); meta['budget_ms'] = 120000 return service.turn(meta, text, pcm, deadline=clock()+120, is_current=lambda: True) try: say(1, '登记我的声纹，我叫测试甲') for n in (2, 3, 4): say(n, '不同的公开合成句子') say(5, '确认保存声纹') meta, pcm = capture(6, boot='test-boot'); meta['budget_ms'] = 120000 original_deadline = clock()+120 first = service.turn(meta, QUESTION, pcm, deadline=original_deadline, is_current=lambda: True) assert '已收到声纹保存提交回执' in first if change == 'expired': clock.now += 60.1 else: def revise(): with service.hub.speaker.store.db: service.hub.speaker.store.db.execute( "UPDATE metadata SET value=value+1 WHERE key='revision'") service.pool.submit(revise).result(1) # Same valid actor/meta, original deadline remains live, _submit accepts # exact replay. A fresh request provides a control for status semantics. replay = service.turn(meta, QUESTION, pcm, deadline=original_deadline, is_current=lambda: True) fresh = say(7, QUESTION) facts = dict(change=change, original_deadline_still_live=clock()<original_deadline, repeated_request_positive='已收到声纹保存提交回执' in replay, fresh_request_unknown='不能判断' in fresh, private_store_accessed=False) (HERE/('replay_'+change+'.json')).write_text(json.dumps(facts, indent=2)+'\n', encoding='utf-8') > assert '不能判断' in replay, facts E AssertionError: {'change': 'expired', 'fresh_request_unknown': True, 'original_deadline_still_live': True, 'private_store_accessed': False, ...} E assert '不能判断' in '本次会话已收到声纹保存提交回执；这不代表说话者身份已确认。'
